    @EventHandler( payloadType=UpdateTransactionEvent.class )
    public void handle( UpdateTransactionEvent event) {
    	LOGGER.info("handling UpdateTransactionEvent - " + event );
    	
	    Transaction entity = new Transaction();
            entity.setTransactionId( event.getTransactionId() );
            entity.setBookingDate( event.getBookingDate() );
            entity.setValueDate( event.getValueDate() );
            entity.setAmount( event.getAmount() );
            entity.setDescription( event.getDescription() );
            entity.setAccount( event.getAccount() );
            entity.setExternalCounterparty( event.getExternalCounterparty() );
            entity.setPaymentCard( event.getPaymentCard() );
            entity.setFundsTransfer( event.getFundsTransfer() );
            entity.setFxTrade( event.getFxTrade() );
            entity.setDispute( event.getDispute() );
            entity.setDirection( event.getDirection() );
            entity.setTransactionType( event.getTransactionType() );
            entity.setStatus( event.getStatus() );
            entity.setChannel( event.getChannel() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindTransaction( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllTransaction( entity );        
    }
    
